import React, { useEffect, useState } from "react";
import api from "../api/api";
import ProductCard from "../components/ProductCard";

const categories = ["All", "Men", "Women", "Kids", "Wedding", "Casual"];

const Shop = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [category, setCategory] = useState("All");
  const [sort, setSort] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    setLoading(true);
    const params = { limit: 24 };
    if (category !== "All") params.category = category;
    if (sort) params.sort = sort;
    if (search) params.search = search;

    api
      .get("/products", { params })
      .then(({ data }) => setProducts(data.products))
      .catch(() => setProducts([]))
      .finally(() => setLoading(false));
  }, [category, sort, search]);

  return (
    <div className="max-w-6xl mx-auto px-5 py-16">
      <h1 className="text-3xl text-ivory mb-2">Shop All Khussa</h1>
      <p className="text-stone text-sm mb-10">Handcrafted pairs for every occasion</p>

      <div className="flex flex-col md:flex-row gap-4 md:items-center md:justify-between mb-10">
        <div className="flex flex-wrap gap-2">
          {categories.map((c) => (
            <button
              key={c}
              onClick={() => setCategory(c)}
              className={`text-xs px-4 py-2 border transition-colors ${
                category === c
                  ? "border-brass text-brass"
                  : "border-brass/20 text-stone hover:text-ivory"
              }`}
            >
              {c}
            </button>
          ))}
        </div>

        <div className="flex gap-3">
          <input
            type="text"
            placeholder="Search khussa..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="bg-charcoal border border-brass/20 text-ivory text-sm px-4 py-2 focus:border-brass outline-none"
          />
          <select
            value={sort}
            onChange={(e) => setSort(e.target.value)}
            className="bg-charcoal border border-brass/20 text-ivory text-sm px-3 py-2 focus:border-brass outline-none"
          >
            <option value="">Sort</option>
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
          </select>
        </div>
      </div>

      {loading ? (
        <p className="text-stone">Loading products...</p>
      ) : products.length === 0 ? (
        <p className="text-stone">
          No products found. Try a different filter, or add products from the admin dashboard.
        </p>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          {products.map((p) => (
            <ProductCard key={p._id} product={p} />
          ))}
        </div>
      )}
    </div>
  );
};

export default Shop;
